-- Nacos dev/prod namespace data export for PostgreSQL
-- Source database: nacos_config
-- Import with: psql -U <user> -d <database> -f nacos_config_dev_prod_import.sql
-- Requires target database schema/tables to already exist.
-- Data format: COPY FROM STDIN, CSV HEADER, NULL as \N.

\set ON_ERROR_STOP on
SET client_encoding = UTF8;
BEGIN;

-- public.tenant_info: 2 rows
COPY public.tenant_info ("id", "kp", "tenant_id", "tenant_name", "tenant_desc", "create_source", "gmt_create", "gmt_modified") FROM stdin WITH (FORMAT csv, HEADER true, NULL \N);
id,kp,tenant_id,tenant_name,tenant_desc,create_source,gmt_create,gmt_modified
"2","1","dev","dev","Xuan ERP development environment","nacos","2026-06-23 02:33:10.714","2026-06-23 02:33:10.714"
"5","1","prod","prod","Xuan ERP production environment","nacos","2026-06-23 02:33:10.989","2026-06-23 02:33:10.989"
\.

-- public.tenant_capacity: 2 rows
COPY public.tenant_capacity ("id", "tenant_id", "quota", "usage", "max_size", "max_aggr_count", "max_aggr_size", "max_history_count", "gmt_create", "gmt_modified") FROM stdin WITH (FORMAT csv, HEADER true, NULL \N);
id,tenant_id,quota,usage,max_size,max_aggr_count,max_aggr_size,max_history_count,gmt_create,gmt_modified
"3","dev","0","58","0","0","0","0","2026-06-23 02:33:11.006","2026-07-06 02:38:08.01"
"6","prod","0","57","0","0","0","0","2026-06-23 02:33:11.825","2026-07-06 02:38:08.015"
\.

-- public.config_info: 115 rows
COPY public.config_info ("id", "data_id", "group_id", "content", "md5", "gmt_create", "gmt_modified", "src_user", "src_ip", "app_name", "tenant_id", "c_desc", "c_use", "effect", "type", "c_schema", "encrypted_data_key") FROM stdin WITH (FORMAT csv, HEADER true, NULL \N);
id,data_id,group_id,content,md5,gmt_create,gmt_modified,src_user,src_ip,app_name,tenant_id,c_desc,c_use,effect,type,c_schema,encrypted_data_key
