"4532","xuan-common.yaml","XUAN_ERP_GROUP","# Xuan ERP common runtime configuration
# Initialized by Codex on 2026-06-23.
# Non-sensitive values only. Passwords, JWT secrets and certificates must stay in server .env or secret manager.

xuan:
  tenant:
    header: X-Tenant-Id
  trace:
    header: X-Trace-Id
  export:
    max-rows: 50000
  upload:
    max-size-mb: 50
  feign:
    connect-timeout: 3000
    read-timeout: 10000
  idempotency:
    header: Idempotency-Key

logging:
  level:
    com.xuan.erp: INFO

springdoc:
  api-docs:
    enabled: true
    path: /v3/api-docs
  swagger-ui:
    enabled: true
    path: /swagger-ui.html

management:
  endpoints:
    web:
      exposure:
        include: health,info,metrics,prometheus
  endpoint:
    health:
      probes:
        enabled: true
