"0","183","xuan-gateway.yaml","XUAN_ERP_GROUP","","# xuan-gateway runtime configuration
# Initialized by Codex on 2026-06-23.
# Namespace: dev

server:
  port: 8100

spring:
  application:
    name: xuan-gateway

  cloud:
    nacos:
      discovery:
        namespace: dev
        group: XUAN_ERP_GROUP
      config:
        namespace: dev
        group: XUAN_ERP_GROUP
        file-extension: yaml

  datasource:
    # Connection location can be centralized here, but password must come from server .env / secret manager.
    url: jdbc:postgresql://postgres:5432/xuan_gateway
    username: xuan_gateway

xuan:
  service:
    name: xuan-gateway
    environment: dev
