"4546","402","xuan-tenant.yaml","XUAN_ERP_GROUP","","# xuan-tenant runtime configuration
# Updated by Codex on 2026-06-27.
# Namespace: dev

server:
  port: 8116

spring:
  application:
    name: xuan-tenant

  cloud:
    nacos:
      discovery:
        namespace: dev
        group: XUAN_ERP_GROUP
      config:
        namespace: dev
        group: XUAN_ERP_GROUP
        file-extension: yaml
    sentinel:
      transport:
        dashboard: duaoyunxuan.com:9022
        port: 8719
      eager: true
      datasource:
        flow:
          nacos:
            server-addr: ${spring.cloud.nacos.config.server-addr}
            namespace: ${spring.cloud.nacos.config.namespace}
            username: ${spring.cloud.nacos.username:nacos}
            password: ${spring.cloud.nacos.password:nacos}
            group-id: XUAN_ERP_GROUP
            data-id: xuan-tenant-sentinel-flow-rules.json
            data-type: json
            rule-type: flow
        degrade:
          nacos:
            server-addr: ${spring.cloud.nacos.config.server-addr}
            namespace: ${spring.cloud.nacos.config.namespace}
            username: ${spring.cloud.nacos.username:nacos}
            password: ${spring.cloud.nacos.password:nacos}
            group-id: XUAN_ERP_GROUP
            data-id: xuan-tenant-sentinel-degrade-rules.json
            data-type: json
            rule-type: degrade
        param-flow:
          nacos:
            server-addr: ${spring.cloud.nacos.config.server-addr}
            namespace: ${spring.cloud.nacos.config.namespace}
            username: ${spring.cloud.nacos.username:nacos}
            password: ${spring.cloud.nacos.password:nacos}
            group-id: XUAN_ERP_GROUP
            data-id: xuan-tenant-sentinel-param-flow-rules.json
            data-type: json
            rule-type: param-flow

  datasource:
    url: jdbc:postgresql://duaoyunxuan.com:9042/xuan_tenant
    username: ${XUAN_DB_USERNAME:nacos}
    password: ${XUAN_DB_PASSWORD}
    driver-class-name: org.postgresql.Driver
  flyway:
    enabled: true
    locations: classpath:db/migration

feign:
  sentinel:
    enabled: true

seata:
  enabled: true
  application-id: ${spring.application.name}
  tx-service-group: xuan-erp-tx-group
  registry:
    type: file
  config:
    type: nacos
    nacos:
      server-addr: ${spring.cloud.nacos.config.server-addr}
