-- Refresh serial sequences after importing explicit id values.
DO $$
DECLARE seq_name text;
BEGIN
  seq_name := pg_get_serial_sequence('public.tenant_info', 'id');
  IF seq_name IS NOT NULL THEN
    EXECUTE format('SELECT setval(%L::regclass, COALESCE((SELECT MAX(id) FROM public.tenant_info), 1), true)', seq_name);
  END IF;
END $$;

DO $$
DECLARE seq_name text;
BEGIN
  seq_name := pg_get_serial_sequence('public.tenant_capacity', 'id');
  IF seq_name IS NOT NULL THEN
    EXECUTE format('SELECT setval(%L::regclass, COALESCE((SELECT MAX(id) FROM public.tenant_capacity), 1), true)', seq_name);
  END IF;
END $$;

DO $$
DECLARE seq_name text;
BEGIN
  seq_name := pg_get_serial_sequence('public.config_info', 'id');
  IF seq_name IS NOT NULL THEN
    EXECUTE format('SELECT setval(%L::regclass, COALESCE((SELECT MAX(id) FROM public.config_info), 1), true)', seq_name);
  END IF;
END $$;

DO $$
DECLARE seq_name text;
BEGIN
  seq_name := pg_get_serial_sequence('public.config_info_gray', 'id');
  IF seq_name IS NOT NULL THEN
    EXECUTE format('SELECT setval(%L::regclass, COALESCE((SELECT MAX(id) FROM public.config_info_gray), 1), true)', seq_name);
  END IF;
END $$;

